                    grid[r+2][0] == color and grid[r+2][1] == color):
                end = c
                while end + 1 < len(row) and row[end+1] == color:
                    end += 1
                bars.append((end-c+1, r, c, end))
    if bars:
        _, r, start, end = min(bars)
        for c in range(end+1, len(grid[r])):
            if grid[r][c] == bg:
                out[r][c] = 1
    return out

